(function (window) {
  function sanitize(html) {
    var template = document.createElement('template');
    template.innerHTML = String(html || '');
    var allowedTags = new Set('A ABBR B BLOCKQUOTE BR CODE DEL DIV EM H1 H2 H3 H4 H5 H6 HR I IMG KBD LI OL P PRE S SPAN STRONG SUB SUP TABLE TBODY TD TH THEAD TR U UL INPUT'.split(' '));
    var allowedAttrs = new Set('href target rel class id title alt src type checked disabled style data-page-id data-level data-prefix'.split(' '));
    template.content.querySelectorAll('*').forEach(function (node) {
      if (!allowedTags.has(node.tagName)) {
        node.replaceWith(document.createTextNode(node.textContent || ''));
        return;
      }
      Array.from(node.attributes).forEach(function (attr) {
        var name = attr.name.toLowerCase();
        var value = attr.value || '';
        if (!allowedAttrs.has(name) && !name.startsWith('aria-')) {
          node.removeAttribute(attr.name);
          return;
        }
        if ((name === 'href' || name === 'src') && /^\s*javascript:/i.test(value)) {
          node.removeAttribute(attr.name);
        }
        if (name === 'style' && /url\s*\(|expression\s*\(/i.test(value)) {
          node.removeAttribute(attr.name);
        }
      });
    });
    return template.innerHTML;
  }
  window.DOMPurify = window.DOMPurify || { sanitize: sanitize };
})(window);
